/**
 * Accepts base64-encoded audio of the student speaking (opening statement,
 * witness question, cross-examination response, or closing argument).
 *
 * The utterance is transcribed and run through the multi-agent courtroom
 * graph, which may put several agents on the floor in sequence: opposing
 * counsel objecting on its own initiative, the judge ruling after reading
 * the governing provisions, then the witness answering if the question
 * survived.
 *
 * Agents are streamed out of the graph as each one finishes, so counsel's
 * objection is spoken while the judge is still reasoning rather than after.
 *
 * The response is an SSE stream. `user_transcript` carries the student's
 * own words; then, for each agent in turn, `speaker` announces who is
 * about to talk (carrying `grounded` provenance with each provision's
 * `verified` flag, and `fabricated` — any citation the audit could not
 * find in the corpus, checked before the line is spoken), `transcript`
 * carries their words, and `audio` carries their synthesized voice as
 * base64 PCM16 at 24 kHz. The stream ends with `{"done": true}`.
 * @summary Submit a spoken turn and receive a streaming AI voice response
 */
export const SendSessionVoiceTurnParams = zod.object({
  "id": zod.coerce.number().int()
})

export const SendSessionVoiceTurnBody = zod.object({
  "audio": zod.string().describe('Base64-encoded audio data of the student\'s spoken turn')
})

export const SendSessionVoiceTurnResponse = zod.unknown()


/**
 * Accepts base64-encoded audio of the student cutting across whoever is
 * speaking. The web app stops playback the moment it hears speech and
 * posts what was said.
 *
 * The utterance is transcribed and classified: an objection is bound to a
 * ground whose provision exists in the corpus, and the same ReAct judge
 * that rules on the agents' objections rules on this one. An interruption
 * that was not an objection returns no ruling rather than being forced
 * into one, and an objection with no citable ground is refused with a
 * direction to state the ground.
 *
 * The response is an SSE stream in the same shape as `voice-turns`:
 * `user_transcript`, then `speaker` / `transcript` / `audio` for the
 * bench, ending with `{"done": true}`. A `note` event carries the reason
 * when nothing was ruled on.
 * @summary Interrupt the court mid-answer with a spoken objection
 */
export const SendSessionInterjectionParams = zod.object({
  "id": zod.coerce.number().int()
})

export const SendSessionInterjectionBody = zod.object({
  "audio": zod.string().describe('Base64-encoded audio data of the student\'s spoken turn')
})

export const SendSessionInterjectionResponse = zod.unknown()


